<section class="container section"><a class="back-link" href="<?= !empty($admin)?'/admin/pedidos':'/cuenta' ?>">← Volver a pedidos</a><div class="section-heading"><div><p class="eyebrow">CREADO ESPECIALMENTE PARA VOS</p><h1>Pedido #<?= $order['id'] ?></h1><p><?= date('d/m/Y H:i',strtotime($order['created_at'])) ?></p></div><span class="badge"><?= e($order['status']) ?></span></div><?php if(isset($_GET['retorno'])): ?><div class="alert">Estamos verificando tu pago con Mercado Pago. El regreso a la tienda no confirma el pago. Si sigue pendiente, actualizá esta página en unos minutos.</div><?php endif ?><div class="checkout-layout"><div><div class="form-panel"><h2>Las piezas de tu pedido</h2><?php foreach($items as $i): ?><div class="order-item"><div><h3><?= $i['quantity'] ?> × <?= e($i['name']) ?></h3><p><?= e($i['lead_time']) ?></p><?php if(($i['dimensions']??'')!==''): ?><p>Medidas: <?= e($i['dimensions']) ?></p><?php endif ?><small><?= money($i['price_cents']) ?> por unidad</small></div><strong><?= money($i['quantity']*$i['price_cents']) ?></strong></div><?php endforeach ?></div><div class="form-panel"><h2>Datos de entrega</h2><p><?= e($order['customer_name']) ?><br><?= e($order['email']) ?><br><?= e($order['phone']) ?></p><strong><?= $order['delivery']==='shipping'?'Envío a domicilio':'Retiro en el taller' ?></strong><p class="preserve"><?= e($order['delivery']==='shipping'?$order['address']:setting('pickup')) ?></p><?php if($order['notes']): ?><h3>Notas</h3><p class="preserve"><?= e($order['notes']) ?></p><?php endif ?></div></div><aside class="summary"><h2>Resumen del pedido</h2><div class="summary-line"><span>Productos</span><strong><?= money($order['subtotal_cents']) ?></strong></div><div class="summary-line"><span>Entrega</span><strong><?= money($order['shipping_cents']) ?></strong></div><div class="summary-line grand-total"><span>Total</span><strong><?= money($order['total_cents']) ?></strong></div><div class="payment-state"><span class="dot"></span> Pago: <?= e(paymentLabel($order['payment_status'])) ?></div><?php if($order['payment_mode']==='test'): ?><p class="microcopy">Pedido en modo de prueba.</p><?php endif ?><?php if(!empty($admin)): ?><form method="post"><?= csrf() ?><label>Estado de fabricación<select name="status"><?php foreach(orderStatuses() as $s): ?><option <?= $s===$order['status']?'selected':'' ?>><?= e($s) ?></option><?php endforeach ?></select></label><button class="btn full">Actualizar estado</button></form><p class="microcopy">Cancelar no devuelve el dinero. Gestioná los reintegros desde Mercado Pago.</p><?php elseif($order['status']!=='cancelado' && !in_array($order['payment_status'],['approved','refunded','charged_back'],true)): ?><?php if(Payments::enabled($order['payment_mode'])): ?><form method="post" action="/pedidos/<?= $order['id'] ?>/pagar"><?= csrf() ?><button class="btn full">Pagar la compra ↗</button></form><p class="microcopy">Te llevamos al sitio de Mercado Pago. Si ya pagaste, esperá la confirmación antes de intentar otra vez.</p><?php else: ?><p class="alert">Los pagos todavía no están habilitados.</p><?php endif ?><?php else: ?><p>Consultá el avance de fabricación en esta página.</p><?php endif ?><a href="<?= e(whatsapp('Hola, quiero consultar por mi pedido #'.$order['id'])) ?>" class="text-link social-link"><?php if(setting('whatsapp')): $socialNetwork='whatsapp'; require ROOT.'/views/social-icon.php'; endif ?>Consultar por mi pedido ↗</a></aside></div></section>
